messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Humanoid Treadmill</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
    </style>
</head>
<body>

<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const CYCLE_DURATION = 10; // seconds
    const STANDING_TIME = 2;
    const WALKING_TIME = 3;
    const RUNNING_TIME = 3;

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x202020);
    scene.fog = new THREE.Fog(0x202020, 10, 50);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 3.5, 10);
    camera.lookAt(0, 1.5, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(5, 10, 7);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 1024;
    dirLight.shadow.mapSize.height = 1024;
    scene.add(dirLight);

    // --- Materials ---
    const skinMaterial = new THREE.MeshStandardMaterial({ color: 0xffccaa, roughness: 0.5 });
    const clothMaterial = new THREE.MeshStandardMaterial({ color: 0x3366cc, roughness: 0.7 });
    const shoeMaterial = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.9 });
    const floorMaterial = new THREE.MeshStandardMaterial({ color: 0x444444 });

    // --- Geometry Helpers ---
    function createLimb(radius, height, material, topY, topX, topZ, pivotY) {
        const geometry = new THREE.BoxGeometry(radius, height, radius);
        const mesh = new THREE.Mesh(geometry, material);
        mesh.position.set(topX, topY, topZ);
        mesh.castShadow = true;
        // Pivot adjustment: mesh origin is center. We want to rotate around the top.
        // We will handle rotation manually in the update loop using a pivot group or by adjusting geometry geometry center.
        // Easier: Just calculate world position in update.
        return mesh;
    }

    // --- The Humanoid Class ---
    class Humanoid {
        constructor() {
            this.group = new THREE.Group();

            // Dimensions
            const hipHeight = 1.2;
            const kneeHeight = 0.8;
            const shoulderHeight = 1.6;
            const neckHeight = 1.85;

            // Body Parts
            // 1. Head
            this.headGeo = new THREE.BoxGeometry(0.35, 0.35, 0.35);
            this.head = new THREE.Mesh(this.headGeo, skinMaterial);
            this.head.position.y = neckHeight + 0.25;
            this.head.castShadow = true;
            this.group.add(this.head);

            // 2. Torso (Upper)
            this.torsoGeo = new THREE.BoxGeometry(0.5, 0.45, 0.3);
            this.torso = new THREE.Mesh(this.torsoGeo, clothMaterial);
            this.torso.position.y = hipHeight + 0.22;
            this.torso.castShadow = true;
            this.group.add(this.torso);

            // 3. Hips (Pivot for legs)
            this.hips = new THREE.Group();
            this.hips.position.y = hipHeight;
            this.group.add(this.hips);

            // 4. Legs
            this.leftUpperLeg = new THREE.Group();
            this.leftUpperLeg.position.set(-0.2, 0, 0);
            this.hips.add(this.leftUpperLeg);

            this.leftShin = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.8, 0.15), skinMaterial);
            this.leftShin.position.y = -0.4;
            this.leftShin.castShadow = true;
            this.leftUpperLeg.add(this.leftShin);

            this.leftShoe = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.12, 0.3), shoeMaterial);
            this.leftShoe.position.set(0, -0.8, 0.05); // Slight forward offset for heel
            this.leftShin.add(this.leftShoe);

            this.rightUpperLeg = new THREE.Group();
            this.rightUpperLeg.position.set(0.2, 0, 0);
            this.hips.add(this.rightUpperLeg);

            this.rightShin = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.8, 0.15), skinMaterial);
            this.rightShin.position.y = -0.4;
           .rightShin.castShadow = true;
            this.rightUpperLeg.add(this.rightShin);

            this.rightShoe = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.12, 0.3), shoeMaterial);
            this.rightShoe.position.set(0, -0.8, 0.05);
            this.rightShin.add(this.rightShoe);

            // 5. Arms
            this.leftShoulder = new THREE.Group();
            this.leftShoulder.position.set(-0.35, shoulderHeight, 0);
            this.group.add(this.leftShoulder);

            this.leftUpperArm = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.35, 0.15), skinMaterial);
            this.leftUpperArm.position.y = -0.17;
            this.leftUpperArm.castShadow = true;
            this.leftShoulder.add(this.leftUpperArm);

            this.leftForearm = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.3, 0.12), skinMaterial);
            this.leftForearm.position.y = -0.3;
            this.leftForearm.castShadow = true;
            this.leftUpperArm.add(this.leftForearm);

            this.rightShoulder = new THREE.Group();
            this.rightShoulder.position.set(0.35, shoulderHeight, 0);
            this.group.add(this.rightShoulder);

            this.rightUpperArm = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.35, 0.15), skinMaterial);
            this.rightUpperArm.position.y = -0.17;
            this.rightUpperArm.castShadow = true;
            this.rightShoulder.add(this.rightUpperArm);

            this.rightForearm = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.3, 0.12), skinMaterial);
            this.rightFoream = this.rightForearm; // alias
            this.rightForearm.position.y = -0.3;
            this.rightForearm.castShadow = true;
            this.rightUpperArm.add(this.rightForearm);

            scene.add(this.group);
        }
    }

    const human = new Humanoid();

    // --- Treadmill Ground ---
    const floorGeo = new THREE.PlaneGeometry(10, 10);
    const floor = new THREE.Mesh(floorGeo, floorMaterial);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    scene.add(floor);

    // --- Animation Logic ---

    function getPhase(time) {
        // time: 0 -> 2 (Stand), 2 -> 5 (Walk), 5 -> 8 (Run), 8 -> 10 (Stand)
        const t = time % CYCLE_DURATION;
        if (t < STANDING_TIME) return 'stand';
        if (t < STANDING_TIME + WALKING_TIME) return 'walk';
        if (t < STANDING_TIME + WALKING_TIME + RUNNING_TIME) return 'run';
        return 'stand';
    }

    // Parameters
    const params = {
        walk: { speed: 4, swing: 0.8, lean: 0.1, armSwing: 0.6, footLift: 0.3 },
        run: { speed: 9, swing: 1.2, lean: 0.3, armSwing: 1.0, footLift: 0.6 },
        stand: { speed: 0, swing: 0, lean: 0, armSwing: 0, footLift: 0 }
    };

    function animateLimb(pivot, time, phase, isRight, isLeg) {
        const p = params[phase];
        const speed = p.speed;
        const swing = p.swing;

        // Phase offset: Right is opposite of Left.
        // If isRight is true, subtract PI from phase.
        const phaseOffset = isRight ? Math.PI : 0;

        // Calculate angle
        // Use sine for smooth swinging
        let angle = Math.sin((time * speed) + phaseOffset) * swing;

        // Add knee bend for walking/running (simple approximation)
        // Knees bend when leg moves back
        let kneeAngle = 0;
        if (phase !== 'stand') {
            // The leg rotates back, knee bends forward
            // We can approximate knee bend based on the sine wave
            const kneeOffset = isRight ? Math.PI : 0;
            const kneeVal = Math.sin((time * speed) + kneeOffset);

            if (isLeg) {
                // Knee bends when leg is swinging forward/up
                kneeAngle = Math.max(0, kneeVal * 0.5); 
            } else {
                // Arm bend
                kneeAngle = Math.max(0, kneeVal * 0.5);
            }
        }

        if (isLeg) {
            // Hip rotation (X axis)
            pivot.rotation.x = -angle;
            // Knee rotation (Z axis relative to upper leg? No, usually Z)
            // Let's make Shin rotate around Z
            pivot.children[0].rotation.z = -kneeAngle; 
        } else {
            // Shoulder rotation (X axis)
            pivot.rotation.x = -angle * 0.8; // Arms swing slightly less than legs
            // Elbow bend
            pivot.children[0].rotation.z = -kneeAngle * 0.5;
        }
    }

    function update(time) {
        const phase = getPhase(time);
        const p = params[phase];

        // Reset
        human.group.rotation.x = 0;
        human.group.position.y = 0;
        human.hips.rotation.x = 0;
        human.hips.rotation.z = 0;

        // Default to stand pose
        human.leftShoulder.rotation.x = 0;
        human.leftUpperArm.rotation.x = 0;
        human.leftForearm.rotation.x = 0;

        human.rightShoulder.rotation.x = 0;
        human.rightUpperArm.rotation.x = 0;
        human.rightForearm.rotation.x = 0;

        human.leftUpperLeg.rotation.x = 0;
        human.leftShin.rotation.z = 0;

        human.rightUpperLeg.rotation.x = 0;
        human.rightShin.rotation.z = 0;

        if (phase === 'stand') {
            // Stand Still
            // Slight breathing animation
            human.group.position.y = Math.sin(time * 2) * 0.02;
            human.head.position.y = 2.1 + Math.sin(time * 2) * 0.02;

        } else if (phase === 'walk' || phase === 'run') {
            // Animate Limbs
            animateLimb(human.leftUpperLeg, time, phase, false, true);
            animateLimb(human.rightUpperLeg, time, phase, true, true);
            animateLimb(human.leftShoulder, time, phase, false, false);
            animateLimb(human.rightShoulder, time, phase, true, false);

            // Apply Lean
            // Run leans forward more
            human.group.rotation.x = p.lean;

            // Hip bob (vertical movement)
            const bobFreq = p.speed;
            const bobAmp = (phase === 'run') ? 0.15 : 0.05;
            human.group.position.y = Math.abs(Math.sin(time * bobFreq)) * bobAmp;

            // Forward lean also slightly pushes hips
            human.hips.position.x = -p.lean * 0.5;
        }
    }

    // --- Loop ---
    const clock = new THREE.Clock();

    function animate() {
        requestAnimationFrame(animate);
        const time = clock.getElapsedTime();
        update(time);
        renderer.render(scene, camera);
    }

    // Handle Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    animate();

</script>
</body>
</html>
```
